From 20eb39fa192f14fec0edbe0a44db214f893876ae Mon Sep 17 00:00:00 2001
From: Duarte Nunes <duarte@scylladb.com>
Date: Wed, 4 May 2016 14:28:02 +0200
Subject: [PATCH] BulkLoader: Allow zero user types to be loaded

This patch fixes a bug introduced by
13b64ad6e3d4841c4f7b49aef0858c196cb2b5e6 which prevented the loader
from working with keyspaces containing no user types.

Fixes #6.

Signed-off-by: Duarte Nunes <duarte@scylladb.com>
Message-Id: <1462364882-31186-1-git-send-email-duarte@scylladb.com>

diff --git a/src/java/com/scylladb/tools/BulkLoader.java b/src/java/com/scylladb/tools/BulkLoader.java
index 20f43652d6..46f879a4d2 100644
--- a/src/java/com/scylladb/tools/BulkLoader.java
+++ b/src/java/com/scylladb/tools/BulkLoader.java
@@ -222,6 +222,9 @@ public class BulkLoader {
         // fixed-point algorithm until we either load all UDTs or fail to make
         // forward progress.
         private static void loadUserTypes(Collection<UserType> udts, KSMetaData ks) {
+            if (udts.isEmpty()) {
+                return;
+            }
             LinkedList<UserType> notLoaded = new LinkedList<UserType>();
             for (UserType ut : udts) {
                 try {
@@ -241,9 +244,7 @@ public class BulkLoader {
             if (notLoaded.size() == udts.size()) {
                 throw new RuntimeException("Unable to load user types " + notLoaded);
             }
-            if (notLoaded.size() > 0) {
-                loadUserTypes(notLoaded, ks);
-            }
+            loadUserTypes(notLoaded, ks);
         }

         private static CQL3Type.Raw getCql3Type(DataType dt) throws Exception {
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the `loadUserTypes` method not handling the case where the collection of user-defined types (UDTs) was empty. This oversight led to the method attempting to process an empty collection, which could result in unexpected behavior or errors during the loading process. The previous change introduced by commit `13b64ad6e3d4841c4f7b49aef0858c196cb2b5e6` did not account for this scenario, thereby breaking the loader's functionality for keyspaces without user types.

        Commit message:
        BulkLoader: Allow zero user types to be loaded

This patch fixes a bug introduced by
13b64ad6e3d4841c4f7b49aef0858c196cb2b5e6 which prevented the loader
from working with keyspaces containing no user types.

Fixes #6.

Signed-off-by: Duarte Nunes <duarte@scylladb.com>
Message-Id: <1462364882-31186-1-git-send-email-duarte@scylladb.com>  

        Patch:
                 // forward progress.
         private static void loadUserTypes(Collection<UserType> udts, KSMetaData ks) {
+            if (udts.isEmpty()) {
+                return;
+            }
             LinkedList<UserType> notLoaded = new LinkedList<UserType>();
             for (UserType ut : udts) {
                 try {
                     ArrayList<ByteBuffer> fieldNames = new ArrayList<ByteBuffer>(ut.getFieldNames().size());
                     ArrayList<AbstractType<?>> fieldTypes = new ArrayList<AbstractType<?>>();
                     for (UserType.Field f : ut) {
                         fieldNames.add(ByteBufferUtil.bytes(f.getName()));
                         fieldTypes.add(getCql3Type(f.getType()).prepare(ks.name).getType());
                     }
                     ks.userTypes.addType(new org.apache.cassandra.db.marshal.UserType(
                         ks.name, ByteBufferUtil.bytes(ut.getTypeName()), fieldNames, fieldTypes));
                 } catch (Exception e) {
                     System.out.println(e);
                     notLoaded.addFirst(ut);
                 }
             }
             if (notLoaded.size() == udts.size()) {
                 throw new RuntimeException("Unable to load user types " + notLoaded);
             }
-            if (notLoaded.size() > 0) {
-                loadUserTypes(notLoaded, ks);
-            }
+            loadUserTypes(notLoaded, ks);
         }



